def addfit(dt,da):
    cols=[t**k for k in range(dt+1)]+[A**k for k in range(1,da+1)]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    return np.mean((dA_dt-X@c)**2)/np.var(dA_dt)
